    slug: "google-ads-lead-gen-affiliate",
    title: "Google Ads Lead Gen Affiliate: A Guide for Publishers",
    metaTitle: "Google Ads Lead Gen Affiliate Guide",
    excerpt: "A guide for affiliates using Google search advertising to generate and monetize high-intent leads.",
    metaDescription: "A guide for affiliates using Google search advertising to generate and monetize high-intent leads, covering campaign structure and compliance rules.",
    category: "Lead Generation Basics",
    readTime: "6 min read",
    publishedDate: "2026-12-07",
